import fs from "node:fs";
import path from "node:path";
import {
  AlignmentType,
  Document,
  Footer,
  Header,
  HeadingLevel,
  Packer,
  PageNumber,
  Paragraph,
  ShadingType,
  Table,
  TableCell,
  TableRow,
  TextRun,
  WidthType,
} from "docx";

const outputPath = process.argv[2];
if (!outputPath) {
  throw new Error("Usage: node build_manuscript_v4.js /absolute/path/output.docx");
}
fs.mkdirSync(path.dirname(outputPath), { recursive: true });

const T = String.raw;
const palette = { dark: "263238", primary: "37474F", light: "78909C", fill: "EEF3F6", ph: "9C3D3D" };
const font = { ascii: "Times New Roman", hAnsi: "Times New Roman", cs: "Times New Roman", eastAsia: "SimSun" };

const run = (text, options = {}) => new TextRun({ text, font, size: 24, ...options });
const phRun = (text) => new TextRun({ text, font, size: 24, italics: true, color: palette.ph });
const para = (children, options = {}) =>
  new Paragraph({
    spacing: { after: 120, line: 360 },
    ...options,
    children: Array.isArray(children) ? children : [children],
  });

const mix = (parts, options = {}) =>
  para(
    parts.map((part) => (typeof part === "string" ? run(part) : phRun(part.ph))),
    options
  );

const h1 = (text) =>
  para(run(text, { bold: true, size: 28, color: palette.dark }), {
    heading: HeadingLevel.HEADING_1,
    spacing: { before: 280, after: 120 },
  });
const h2 = (text) =>
  para(run(text, { bold: true, size: 24, color: palette.primary }), {
    heading: HeadingLevel.HEADING_2,
    spacing: { before: 200, after: 100 },
  });
const caption = (text) =>
  para(run(text, { bold: true, size: 22, color: palette.primary }), { spacing: { before: 160, after: 80 } });

const cell = (parts, width, options = {}) =>
  new TableCell({
    children: [
      new Paragraph({
        spacing: { after: 20, line: 260 },
        children: Array.isArray(parts)
          ? parts.map((part) => (typeof part === "string" ? run(part, { size: 20 }) : phRun(part.ph)))
          : [run(parts, { size: 20 })],
      }),
    ],
    margins: { top: 80, bottom: 80, left: 90, right: 90 },
    width: { size: width, type: WidthType.DXA },
    ...options,
  });

const makeTable = (widths, headerRow, bodyRows) =>
  new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    columnWidths: widths,
    rows: [
      new TableRow({
        tableHeader: true,
        children: headerRow.map((text, i) =>
          cell(text, widths[i], { shading: { type: ShadingType.CLEAR, fill: palette.fill } })
        ),
      }),
      ...bodyRows.map((row) => new TableRow({ children: row.map((parts, i) => cell(parts, widths[i])) })),
    ],
  });

// ---- result tables are read from TSVs generated by aggregate_supplement_v4.py ----
