const readTsv = (p) => {
  const lines = fs.readFileSync(p, "utf8").trim().split(/\r?\n/);
  return { header: lines[0].split("\t"), rows: lines.slice(1).map((l) => l.split("\t")) };
};
const T2 = readTsv(path.join(TBLDIR, "T2_main.tsv"));
const T3 = readTsv(path.join(TBLDIR, "T3_sensitivity_nielsen.tsv"));
